import unittest
from candidate import incr_list

class TestIncrList(unittest.TestCase):
    def test_incr_list_normal_positive(self):
        self.assertEqual(incr_list([1, 2, 3]), [2, 3, 4])

    def test_incr_list_normal_negative(self):
        self.assertEqual(incr_list([-5, -1, -10]), [-4, 0, -9])

    def test_incr_list_mixed_signs(self):
        self.assertEqual(incr_list([-2, 0, 3]), [-1, 1, 4])

    def test_incr_list_with_zeros(self):
        self.assertEqual(incr_list([0, 0, 0]), [1, 1, 1])

    def test_incr_list_large_numbers(self):
        self.assertEqual(incr_list([999999, 123456789]), [1000000, 123456790])

    def test_incr_list_empty(self):
        self.assertEqual(incr_list([]), [])

    def test_incr_list_single_element(self):
        self.assertEqual(incr_list([42]), [43])

    def test_incr_list_floats(self):
        self.assertEqual(incr_list([1.5, 2.5, 3.0]), [2.5, 3.5, 4.0])

    def test_incr_list_none_input(self):
        with self.assertRaises(TypeError):
            incr_list(None)

    def test_incr_list_non_iterable(self):
        with self.assertRaises(TypeError):
            incr_list(123)

    def test_incr_list_contains_string(self):
        with self.assertRaises(TypeError):
            incr_list([1, "two", 3])

if __name__ == '__main__':
    unittest.main()
